#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/rooms/keys/chain/0.1#request\",\n  \"issuer\": \"did:example:member\",\n  \"recipient\": \"did:example:keyholder\",\n  \"issuedAt\": \"2026-01-01T00:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n    \"links\": [\n      { \"epoch\": 4, \"wrapped\": \"Lp3wXc9TgYw2mQnR4vBk8Q\", \"nonce\": \"c1Au9Rn3Zr2tWwS1\" },\n      { \"epoch\": 3, \"wrapped\": \"Tf6yNb2VhZx5pRoS7wCl9Q\", \"nonce\": \"d2Bv0So4As3uXxT2\" },\n      { \"epoch\": 2, \"wrapped\": \"Wq8zMd4XjBy7rTqU9yEn1Q\", \"nonce\": \"e3Cw1Tp5Bt4vYyU3\" }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/rooms/keys/chain/0.1#response\",\n  \"issuer\": \"did:example:keyholder\",\n  \"recipient\": \"did:example:member\",\n  \"issuedAt\": \"2026-01-01T00:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000000ff\",\n  \"payload\": {\n    \"roomId\": \"did:webvh:example.com:rooms:northwind\",\n    \"earliestReadableEpoch\": 1,\n    \"stored\": 3\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "An empty links array. A delivery that carries no rungs asks the recipient to retain nothing and report on nothing; `minItems: 1` makes the caller say what they meant rather than receive a success that changed no state.",
                "{\n  \"links\": [],\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "No links member at all. The rungs are the entire payload — a request without them is a request to do nothing, and there is no defaulting that would be honest.",
                "{\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "A rung claiming epoch 1. A room's first epoch has no predecessor, so rung 1 wraps something that is not an earlier epoch's key; EpochLink's floor of 2 refuses it before it can be stored as a rung that silently ends the walk.",
                "{\n  \"links\": [\n    {\n      \"epoch\": 1,\n      \"nonce\": \"b0Zt8Qm2Yq1sVvR0\",\n      \"wrapped\": \"9jK2_QhV1sVvR0m5xAqZ7A\"\n    }\n  ],\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "A rung with no wrapped key. The nonce alone is not a rung; storing one would extend the chain's length without extending its reach, which is the shape of a gap that looks like a delivery.",
                "{\n  \"links\": [\n    {\n      \"epoch\": 3,\n      \"nonce\": \"b0Zt8Qm2Yq1sVvR0\"\n    }\n  ],\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "An unknown member inside a rung — additionalProperties: false on EpochLink. A rung carries wrapped key material and nothing descriptive; an extra member is the obvious place to leak what the sealing exists to hide.",
                "{\n  \"links\": [\n    {\n      \"epoch\": 3,\n      \"joinedAt\": \"2026-01-01T00:00:00Z\",\n      \"nonce\": \"b0Zt8Qm2Yq1sVvR0\",\n      \"wrapped\": \"9jK2_QhV1sVvR0m5xAqZ7A\"\n    }\n  ],\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
            (
                "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
                "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  },\n  \"links\": [\n    {\n      \"epoch\": 2,\n      \"nonce\": \"b0Zt8Qm2Yq1sVvR0\",\n      \"wrapped\": \"9jK2_QhV1sVvR0m5xAqZ7A\"\n    }\n  ],\n  \"roomId\": \"did:webvh:example.com:rooms:northwind\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
